import { getBackendActor } from '../ic/actor.js';
import { geminiService } from './GeminiService.js';

class ChatService {
  constructor() {
    this.actor = null;
    this.maxContextMessages = 5; // keep last 5 messages for context
    this.initializeActor();
  }

  async initializeActor() {
    try {
      this.actor = await getBackendActor();
    } catch (error) {
      console.error('❌ Failed to initialize ICP actor:', error);
    }
  }

  // Helper: get recent messages for context
  async getContextMessages() {
    try {
      const history = await this.getChatHistory();
      return history.slice(-this.maxContextMessages).map(m => ({
        role: m.isBot ? 'assistant' : 'user',
        content: m.text,
      }));
    } catch (error) {
      console.error("⚠️ Couldn't fetch context messages:", error);
      return [];
    }
  }

  // Main chat processing function
  async processChat(userMessage, userProfile) {
    try {
      if (!this.actor) {
        await this.initializeActor();
      }

      // Step 1: Store user message in ICP backend
      await this.actor.addMessage(userMessage, Date.now() * 1000000);

      // Step 2: Get context (last few messages)
      const context = await this.getContextMessages();

      // Step 3: Detect emotion
      const emotion = await geminiService.detectEmotion(userMessage);

      // Step 4: Extract investment entities
      const entities = await geminiService.extractInvestmentEntities(userMessage);

      // Step 5: Generate advice (with retry)
      let response;
      try {
        response = await geminiService.generateFinancialAdvice(
          userMessage,
          userProfile,
          emotion,
          entities,
          context
        );
      } catch (err) {
        console.warn("⚠️ Gemini call failed, retrying once...");
        response = await geminiService.generateFinancialAdvice(
          userMessage,
          userProfile,
          emotion,
          entities,
          context
        );
      }

      // Step 6: Store bot response
      await this.actor.addBotMessage(response.advice, emotion);

      // Step 7: Store analytics
      await this.actor.storeChatInteraction(
        userMessage,
        response.advice,
        emotion,
        entities
      );

      // Step 8: Return with typing simulation flag
      return {
        ...response,
        typing: true, // frontend can use this
      };

    } catch (error) {
      console.error('❌ Chat processing failed:', error);
      return this.getFallbackResponse(userProfile, 'neutral');
    }
  }

  // Update user memory in ICP backend
  async updateUserMemory(data) {
    if (!this.actor) return;
    try {
      return await this.actor.updateUserProfile(
        data.name ? [data.name] : [],
        data.salary ? [data.salary] : [],
        data.expenses ? [data.expenses] : [],
        data.risk_tolerance ? [data.risk_tolerance] : [],
        data.target_savings ? [data.target_savings] : [],
        data.country ? [data.country] : [],
        data.language ? [data.language] : [],
        data.life_stage ? [data.life_stage] : [],
        data.goals ? [data.goals] : []
      );
    } catch (error) {
      console.error('❌ Failed to update user profile:', error);
    }
  }

  async getUserData() {
    try {
      return this.actor ? await this.actor.getUserProfile() : null;
    } catch (error) {
      console.error('❌ Failed to get user data:', error);
      return null;
    }
  }

  async getChatHistory() {
    try {
      return this.actor ? await this.actor.getMessages() : [];
    } catch (error) {
      console.error('❌ Failed to get chat history:', error);
      return [];
    }
  }

  async getChatInteractions() {
    try {
      return this.actor ? await this.actor.getChatInteractions() : [];
    } catch (error) {
      console.error('❌ Failed to get chat interactions:', error);
      return [];
    }
  }

  async deleteUserData() {
    try {
      return this.actor ? await this.actor.deleteUserData() : false;
    } catch (error) {
      console.error('❌ Failed to delete user data:', error);
      return false;
    }
  }

  async exportUserData() {
    try {
      return this.actor ? await this.actor.exportUserData() : null;
    } catch (error) {
      console.error('❌ Failed to export user data:', error);
      return null;
    }
  }

  // Fallback response
  getFallbackResponse(userProfile, emotion) {
    return {
      advice: `Hello ${userProfile?.name || "there"}! I'm facing technical difficulties right now, but here's some general advice:

With your income of ₹${userProfile?.salary || 0} and expenses of ₹${userProfile?.expenses || 0}, 
your monthly surplus is about ₹${(userProfile?.salary || 0) - (userProfile?.expenses || 0)}.

💡 Tips:
• Build an emergency fund
• Try SIPs for disciplined investing
• Look into ELSS for tax-saving

Please try asking again soon!`,
      emotion,
      suggestions: [
        'Help me create a budget plan',
        'What are safe investment options?',
        'How should I start investing?',
      ],
      resources: [
        'Financial Planning Basics',
        'Investment Guide for Beginners',
        'Emergency Fund Calculator',
        'SIP Calculator',
      ],
      typing: false,
    };
  }
}

export const chatService = new ChatService();
